{
  "understanding": {
    "purpose": "记录会议行动项，明确负责人、截止日期和执行状态，便于后续跟进。",
    "reading": "读者先按行识别行动项，再横向查看负责人、截止日期和状态；也会纵向扫描截止日期和状态以确定跟进优先级。较长的行动项会形成多行，同行的其他单元格可利用这些行高。",
    "groups": [
      "负责人、Due 和状态共同描述行动项的执行与跟进信息。",
      "# 和 Action item 共同用于定位和识别每条任务。"
    ],
    "keep_intact": [
      "序号",
      "负责人姓名中的不可拆分部分",
      "截止日期",
      "状态标签中的不可拆分部分",
      "英文单词、缩写和产品名称中的不可拆分部分"
    ],
    "may_wrap": [
      "行动项描述可在中文字符之间或英文单词之间自然换行。",
      "由多个词组成的负责人或状态值可在自然边界换行。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [32, 230, 74, 64, 79],
      "idea": "均衡分配空间，让行动项有主要阅读宽度，同时为负责人和状态保留完整单行宽度。"
    },
    {
      "name": "B",
      "widths": [32, 270, 55, 56, 66],
      "idea": "优先拓宽行动项，减少长描述的换行，接受负责人和状态在自然边界换行。"
    },
    {
      "name": "C",
      "widths": [32, 210, 74, 84, 79],
      "idea": "优先保证跟进信息的清晰扫描，给截止日期更多空间，并让行动项承担更多换行。"
    }
  ]
}
